#!/usr/bin/env python3
"""Render every generated file in the repository from a :class:`model.Catalog`.

Pure: ``build(catalog, today)`` returns ``{path: text}`` and touches nothing, so
the tests can render the whole repository from a fixture and compare bytes.

The layout has one axis, the company:

    README.md                      a short index: one table of companies
    companies/<key>/README.md      that company's OA questions, newest first
    companies/<key>/oa.csv         the same rows as data
    data/questions.csv|jsonl       every OA row, with its companies

Only questions the catalog tags with the ``oa`` round are listed. A company
with no such question gets no folder.
"""

from __future__ import annotations

import csv
import io
import json
from datetime import date

from model import DIFFICULTY_SHORT, FORMAT_SHORT, LEVEL_SHORT, Catalog, Question, last_reported, newest_first

SITE = "https://trueinterview.io"
REPO = "kevin-2023-code/Tech-OA-Questions"
SISTER = "https://github.com/kevin-2023-code/Tech-Interview-Questions"
SUBMIT = f"https://github.com/{REPO}/issues/new?template=oa-report.yml"

GENERATED = "<!-- Generated by scripts/sync.py from the TrueInterview catalog. Do not edit by hand: the next sync overwrites it. -->"

#: GitHub truncates a rendered markdown file at 512,000 bytes. Both budgets leave
#: a wide margin, and sync.py writes NOTHING when one is exceeded. The README is
#: an index of one line per company, so its budget is the tighter one.
README_MAX_BYTES = 60_000
PAGE_MAX_BYTES = 400_000

#: The columns of every CSV, in order. ``data/questions.csv`` puts COMPANY_COLUMN first.
COLUMNS = ("Title", "Format", "Difficulty", "Level", "Role", "Last Reported", "Link")
COMPANY_COLUMN = "Company"

#: The keys of :func:`record`, in the order of COLUMNS.
FIELDS = ("title", "format", "difficulty", "level", "role", "last_reported", "link")


# ── Cells ────────────────────────────────────────────────────────────────────


def esc(text: str) -> str:
    """Make free text safe inside a table cell and a link label."""
    return (
        text.replace("\\", "\\\\")
        .replace("|", "\\|")
        .replace("[", "\\[")
        .replace("]", "\\]")
        .replace("<", "&lt;")
        .replace("\n", " ")
    )


def num(n: int) -> str:
    return f"{n:,}"


def role_values(q: Question) -> tuple[str, ...]:
    """The role titles the catalog publishes, or the broader role groups when
    the question was not classified that finely. Never derived from anything else."""
    return q.role_titles or q.roles


def record(q: Question, today: date) -> dict:
    """One question as the fields this repository publishes: metadata only."""
    return {
        "title": q.title,
        "format": FORMAT_SHORT.get(q.format, q.format),
        "difficulty": DIFFICULTY_SHORT.get(q.difficulty or "", q.difficulty or ""),
        "level": [LEVEL_SHORT[level] for level in q.levels],
        "role": list(role_values(q)),
        "last_reported": last_reported(q, today),
        "link": q.url,
    }


def csv_row(q: Question, today: date) -> list[str]:
    r = record(q, today)
    return ["; ".join(r[key]) if isinstance(r[key], list) else r[key] for key in FIELDS]


def to_csv(header: tuple[str, ...], rows: list[list[str]]) -> str:
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(header)
    writer.writerows(rows)
    return buffer.getvalue()


# ── Selection ────────────────────────────────────────────────────────────────


def oa_questions(catalog: Catalog, today: date) -> list[Question]:
    return newest_first([q for q in catalog.questions if q.is_oa], today)


def by_company(questions: list[Question]) -> dict[str, tuple[str, list[Question]]]:
    """``{key: (display name, rows)}``, rows in the order given."""
    out: dict[str, tuple[str, list[Question]]] = {}
    for q in questions:
        for key, name in zip(q.company_keys, q.companies):
            out.setdefault(key, (name, []))[1].append(q)
    return out


def company_order(groups: dict[str, tuple[str, list[Question]]]) -> list[str]:
    """Most OA questions first, then by name, then by key so ties never move."""
    return sorted(groups, key=lambda key: (-len(groups[key][1]), groups[key][0].lower(), key))


# ── Pages ────────────────────────────────────────────────────────────────────


def build_company(name: str, rows: list[Question], today: date) -> dict[str, str]:
    lines = [
        GENERATED,
        "",
        f"# {esc(name)} OA Questions",
        "",
        f"{num(len(rows))} online assessment question{'' if len(rows) == 1 else 's'} reported at {esc(name)}, newest first. "
        "The same rows as data: [oa.csv](oa.csv). Back to [all companies](../../README.md).",
        "",
        "| Title | Format | Difficulty | Level | Role | Last Reported |",
        "| :-- | :-- | :-- | :-- | :-- | :-- |",
    ]
    for q in rows:
        r = record(q, today)
        cells = [
            f"[{esc(r['title'])}]({r['link']})",
            esc(r["format"]),
            r["difficulty"],
            ", ".join(r["level"]),
            esc(", ".join(r["role"])),
            r["last_reported"],
        ]
        lines.append("| " + " | ".join(cell or "-" for cell in cells) + " |")
    return {
        "README.md": "\n".join(lines) + "\n",
        "oa.csv": to_csv(COLUMNS, [csv_row(q, today) for q in rows]),
    }


def build_data(questions: list[Question], today: date) -> dict[str, str]:
    """Every OA row once, with its companies. ``questions.jsonl`` carries the
    same fields under lower-case keys, lists kept as lists."""
    ordered = sorted(questions, key=lambda q: (tuple(c.lower() for c in q.companies), q.title.lower(), q.slug))
    rows = [["; ".join(q.companies), *csv_row(q, today)] for q in ordered]
    jsonl = "".join(
        json.dumps({"company": list(q.companies), **record(q, today)}, ensure_ascii=False, sort_keys=True) + "\n" for q in ordered
    )
    return {"data/questions.csv": to_csv((COMPANY_COLUMN, *COLUMNS), rows), "data/questions.jsonl": jsonl}


def build_readme(questions: list[Question], groups: dict[str, tuple[str, list[Question]]], today: date) -> str:
    lines = [
        GENERATED,
        "",
        "# Tech OA Questions",
        "",
        "Online assessment (OA) questions candidates reported at tech companies, one folder per company.",
        "",
        f"**Snapshot as of {today.isoformat()}: {num(len(questions))} OA questions from {num(len(groups))} companies.**",
        "",
        f"The question pages are on [TrueInterview]({SITE}).",
        "",
        "## How to use",
        "",
        "- Pick a company in the table below. Its folder has `README.md` (the questions as a table, newest first) and `oa.csv` (the same rows as data).",
        "- Every row in one file: [data/questions.csv](data/questions.csv) and [data/questions.jsonl](data/questions.jsonl).",
        f"- Phone screen, onsite and take-home questions are in the sibling repository [Tech-Interview-Questions]({SISTER}).",
        "",
        "## Columns",
        "",
        "- **Title**: the question title, linked to its page.",
        "- **Format**: Coding, SQL, OOD / LLD, System design, AI coding, or Behavioral / concept.",
        "- **Difficulty**: Easy, Medium or Hard. Empty for formats that have no difficulty.",
        "- **Level**: the levels it was reported at (Intern, New grad, Mid, Senior, Staff+, Manager).",
        "- **Role**: the role it was reported for.",
        "- **Last Reported**: the month of the most recent report, `YYYY-MM`. Empty when unknown.",
        "- **Link**: the question page (CSV only; in the tables the title is the link).",
        "",
        "A question is listed when the catalog tags it with the OA round. The tag belongs to the question, "
        "so a question reported at several companies is listed under each of them. "
        "Only metadata is published here: no statements and no solutions.",
        "",
        "## Companies",
        "",
        "| Company | OA questions | Newest OA |",
        "| :-- | --: | :-- |",
    ]
    for key in company_order(groups):
        name, rows = groups[key]
        newest = max((last_reported(q, today) for q in rows), default="")
        lines.append(f"| [{esc(name)}](companies/{key}/README.md) | {num(len(rows))} | {newest or '-'} |")
    lines += [
        "",
        "## Contributing",
        "",
        f"Saw an OA question that is missing? [Submit it]({SUBMIT}). Corrections and local setup: [CONTRIBUTING.md](CONTRIBUTING.md).",
        "",
        "## Licence",
        "",
        "Code is MIT-licensed, see [LICENSE](LICENSE). Questions are listed by title and metadata only.",
        "",
        "If this list helps you, a star helps the next candidate find it.",
    ]
    return "\n".join(lines) + "\n"


# ── Everything ───────────────────────────────────────────────────────────────


def build(catalog: Catalog, today: date) -> dict[str, str]:
    questions = oa_questions(catalog, today)
    groups = by_company(questions)
    files: dict[str, str] = {"README.md": build_readme(questions, groups, today)}
    for key, (name, rows) in groups.items():
        for filename, text in build_company(name, rows, today).items():
            files[f"companies/{key}/{filename}"] = text
    files.update(build_data(questions, today))
    return files


def over_budget(files: dict[str, str]) -> list[str]:
    problems = []
    for path, text in files.items():
        if not path.endswith(".md"):
            continue
        size = len(text.encode("utf-8"))
        limit = README_MAX_BYTES if path == "README.md" else PAGE_MAX_BYTES
        if size > limit:
            problems.append(f"{path}: {size:,} bytes > {limit:,}")
    return problems
